\label{thm:symto}
Given unimodular complex numbers $\rho$ and $\gamma$, complex numbers
$u$ and $c$, and nonnegative real numbers $v$ and $s$ such
that $|u|^2 + v^2 = 1$ and $|c|^2 + s^2 = 1$, define the
following, 
\begin{equation*}
\begin{array}{l}
\begin{array}{lll}
p &=& -\rho(c + \overline{\gamma}\overline{c} u), \\
n &=& \sqrt{|p|^2 + v^2},
\end{array} \\
\begin{array}{llll}
\mathrm{if}\ n \neq 0: & & &\\
& \widehat{c} &=& p/n,\\
& \widehat{s} &=& v/n,\\
& \widehat{u} &=& \overline{\rho}(s^2u - \gamma c^2),\\
& \widehat{v} &=& s n\\
\mathrm{else}: & & &\\
& \widehat{c} &=& 0,\\
& \widehat{s} &=& 1,\\
& \widehat{u} &=& \overline{\rho} u,\\
& \widehat{v} &=& 0,\\
\end{array} \\
\begin{array}{lll}
\widehat{\gamma} &=& -\overline{\rho}\gamma.
\end{array}
\end{array}
\end{equation*}
Then, the following products are equivalent,
\[
\begin{bmatrix}
-\overline{\rho} \gamma c & \phantom{-{}}\overline{\rho} s  & \\
-\rho s & -\rho\overline{\gamma} \overline{c} & \\
     &                & 1 
\end{bmatrix}
\begin{bmatrix}
 1    &                & \\  
 &  u & -v           \\
 &  v & \phantom{-{}}\overline{u}
\end{bmatrix}
\begin{bmatrix}
 c & -s           & \\
 s & \phantom{-{}}\overline{c} \\
     &                & 1 
\end{bmatrix}
= 
\begin{bmatrix}
 1    &                & \\  
 & \widehat{c} & -\widehat{s}           \\
 & \widehat{s} & \phantom{-{}}\overline{\widehat{c}}
\end{bmatrix}
\begin{bmatrix}
 \widehat{u} & -\widehat{v}           & \\
 \widehat{v} & \phantom{-{}}\overline{\widehat{u}} \\
     &                & 1 
\end{bmatrix}
\begin{bmatrix}
 1    &                & \\  
 & -\overline{\rho}\widehat{\gamma}\widehat{c} & \phantom{-{}}\overline{\rho}\widehat{s}           \\
 &  -\rho \widehat{s} & -\rho\overline{\widehat{\gamma}}\overline{\widehat{c}}
\end{bmatrix}.
\]

\label{cor:symto}
Given unimodular complex numbers $\rho$, $\gamma$ and $\sigma$, a complex number $u$,
and nonnegative real numbers $v$, $c$ and $s$ such that $|u|^2 + v^2 = 1$ and
$c^2 + s^2 = 1$, define the following, 
\begin{equation*}
\begin{array}{l}
\begin{array}{lll}
t &=& \overline{\gamma}\overline{\sigma}^2 u,
\end{array} \\
\begin{array}{lll}
z &=&        
\begin{cases}
1+t, & \operatorname{Re}(t) \geq 0,\\
\frac{v^2 + 2\operatorname{Im}(t)i}{1-\overline{t}}, & \operatorname{Re}(t) < 0,
\end{cases}
\end{array} \\
\begin{array}{lll}
n &=& \sqrt{c^2|z|^2 + v^2},
\end{array} \\
\begin{array}{llll}
\mathrm{if}\ n \neq 0: & & &\\
& \widehat{c} &=& c|z|/n,\\
& \widehat{\sigma} &=& -\rho \sigma z/|z|,\\
& \widehat{s} &=& v/n,\\
& \widehat{u} &=& \overline{\rho}(s^2u - \gamma\sigma^2c^2),\\
& \widehat{v} &=& s n\\
\mathrm{else}: & & &\\
& \widehat{c} &=& 0,\\
& \widehat{\sigma} &=& 1,\\
& \widehat{s} &=& 1,\\
& \widehat{u} &=& \overline{\rho} u,\\
& \widehat{v} &=& 0,\\
\end{array} \\
\begin{array}{lll}
\widehat{\gamma} &=& -\overline{\rho}\gamma.
\end{array}
\end{array}
\end{equation*}
Then, 
\[
\mathpalette 
  \ooalign{ 
    \hfil$\m@th Q$\hfil\cr
    \hidewidth\raisebox{-0.35ex}{$\m@th\widetilde{\phantom{Q}}$}\hidewidth\cr
  } 
 Q = \widehat{Q} \widehat{U} \smash{\widehat{\mathpalette\tQ@{}}}.
\]

\label{cor:rfsymto}
Given unimodular complex numbers $\rho$, $\gamma$  and $\omega$, a complex
number $u$, and nonnegative real numbers $vv$, $cc$ and $ss$ such that
$|u|^2 + vv = 1$ and $cc + ss = 1$, define the following, 
\begin{center}
\begin{tikzpicture}[scale=1.00,y=-5mm,x=5mm]
\node at (0.0,0.0) [align=left, anchor=west] {$t$};
\node at (1.0,0.0) [align=left, anchor=west] {$=$};
\node at (2.0,0.0) [align=left, anchor=west] {$\overline{\omega} u,$};

\node at (0.0,2.0) [align=left, anchor=west] {$z$};
\node at (1.0,2.0) [align=left, anchor=west] {$=$};
\draw[
  decorate,
  decoration={brace, amplitude=6pt}
] (2.5,3.5) -- (2.5,0.5);
\node at (2.5,1.0) [align=left, anchor=west] {$1+t,$};
\node at (7.0,1.0) [align=left, anchor=west] {$\operatorname{Re}(t) \geq 0,$};
\node at (2.5,2.5) [align=left, anchor=west] {$\dfrac{vv + 2\operatorname{Im}(t) i}{1-\overline{t}},$};
\node at (7.0,2.5) [align=left, anchor=west] {$\operatorname{Re}(t) < 0,$};

\node at (0.0,4.0) [align=left, anchor=west] {$nn$};
\node at (1.0,4.0) [align=left, anchor=west] {$=$};
\node at (2.0,4.0) [align=left, anchor=west] {$cc\cdot |z|^2 + vv,$};

\node at (0.0,5.0) [align=left, anchor=west] {$\mathrm{if}\ nn \neq 0:$};

\node at (1.0,6.0) [align=left, anchor=west] {$\widehat{cc}$};
\node at (2.0,6.0) [align=left, anchor=west] {$=$};
\node at (3.0,6.0) [align=left, anchor=west] {$cc\cdot |z|^2/nn,$};

\node at (1.0,7.0) [align=left, anchor=west] {$\widehat{ss}$};
\node at (2.0,7.0) [align=left, anchor=west] {$=$};
\node at (3.0,7.0) [align=left, anchor=west] {$vv/nn,$};

\node at (1.0,8.0) [align=left, anchor=west] {$\widehat{u}$};
\node at (2.0,8.0) [align=left, anchor=west] {$=$};
\node at (3.0,8.0) [align=left, anchor=west] {$\overline{\rho}(ss\cdot u - cc\cdot\omega),$};

\node at (1.0,9.0) [align=left, anchor=west] {$\widehat{vv}$};
\node at (2.0,9.0) [align=left, anchor=west] {$=$};
\node at (3.0,9.0) [align=left, anchor=west] {$ss\cdot nn,$};

\node at (1.0,10.0) [align=left, anchor=west] {$\widehat{\omega}$};
\node at (2.0,10.0) [align=left, anchor=west] {$=$};
\node at (3.0,10.0) [align=left, anchor=west] {$-\rho \omega z^2/|z|^2,$};

\node at (0.0,11.0) [align=left, anchor=west] {$\mathrm{else}:$};

\node at (1.0,12.0) [align=left, anchor=west] {$\widehat{cc}$};
\node at (2.0,12.0) [align=left, anchor=west] {$=$};
\node at (3.0,12.0) [align=left, anchor=west] {$0,$};

\node at (1.0,13.0) [align=left, anchor=west] {$\widehat{ss}$};
\node at (2.0,13.0) [align=left, anchor=west] {$=$};
\node at (3.0,13.0) [align=left, anchor=west] {$1,$};

\node at (1.0,14.0) [align=left, anchor=west] {$\widehat{u}$};
\node at (2.0,14.0) [align=left, anchor=west] {$=$};
\node at (3.0,14.0) [align=left, anchor=west] {$\overline{\rho} u,$};

\node at (1.0,15.0) [align=left, anchor=west] {$\widehat{vv}$};
\node at (2.0,15.0) [align=left, anchor=west] {$=$};
\node at (3.0,15.0) [align=left, anchor=west] {$0,$};

\node at (1.0,16.0) [align=left, anchor=west] {$\widehat{\omega}$};
\node at (2.0,16.0) [align=left, anchor=west] {$=$};
\node at (3.0,16.0) [align=left, anchor=west] {$1.$};
\end{tikzpicture}
\end{center}
Then, for
\[
u,
\quad
v = \sqrt{vv},
\quad
c = \sqrt{cc},
\quad
s = \sqrt{ss},
\quad
\sigma = \sqrt{\overline{\gamma}\omega},
\quad
\gamma,
\quad
\rho,
\]
and
\[
\widehat{u},
\quad
\widehat{v} = \sqrt{\widehat{vv}},
\quad
\widehat{c} = \sqrt{\widehat{cc}},
\quad
\widehat{s} = \sqrt{\widehat{ss}},
\quad
\widehat{\sigma} = \sqrt{\overline{\widehat{\gamma}}\widehat{\omega}},
\quad
\widehat{\gamma} = -\overline{\rho}\gamma,
\]
where the square roots are chosen so that the real variables are nonnegative
and $\widehat{\sigma} = -\rho \sigma z/|z|$,
\[
\mathpalette 
  \ooalign{ 
    \hfil$\m@th Q$\hfil\cr
    \hidewidth\raisebox{-0.35ex}{$\m@th\widetilde{\phantom{Q}}$}\hidewidth\cr
  } 
 Q = \widehat{Q} \widehat{U} \smash{\widehat{\mathpalette\tQ@{}}}.
\]
